-- 0050 F18 结束条件与业务恢复选项（P1-08）
-- 依据：评审 P1-08 —— F18《应急响应结束记录单》原提示只让核对「四项结束条件」，
-- 而 S06-13 要求核对五项（接口关闭、证据固定、患者告知、舆情可控、上报/报案闭环）；
-- 原「业务恢复确认」只列 HIS/工作站/EMR/LIS/PACS/OA 六个系统，S07/S08 无法选择
-- 网络出口/邮件/办公终端。本迁移只新增字段、追加选项、改提示文案，不删除任何已有选项，
-- 保证历史 form_submissions 按 label 回显不受影响。
-- 纯 DML，固定终值，可重复执行。

UPDATE form_templates
   SET fields = '[{"label":"响应级别","type":"select","options":["Ⅰ级","Ⅱ级","Ⅲ级","Ⅳ级"],"required":true,"hint":"本次结束的应急响应级别，须与启动审批一致。"},{"label":"结束依据","type":"textarea","required":true,"hint":"按本场景节点说明逐条核对结束条件（S01 四项、S06 五项，S07/S08 按网络/终端口径），并引用预案条款；逐项结论请在「结束条件核对」中勾选。"},{"label":"事件处置结论","type":"textarea","required":true,"hint":"事件定性、处置结果与损失情况概述。"},{"label":"业务恢复确认","type":"multiselect","options":["HIS收费系统","医护工作站","电子病历系统","临床检验系统","医学影像系统","办公OA系统","网络出口/防火墙","邮件系统","办公终端/终端管理","医疗设备网络"],"required":true,"hint":"勾选已恢复并经确认的业务系统或网络/终端；未恢复项在残余风险中说明。"},{"label":"残余风险与后续措施","type":"textarea","required":true,"hint":"未闭环风险、观察期安排、整改责任人与完成时限。"},{"label":"批准人","type":"text","required":true,"hint":"批准结束响应的指挥人员姓名与职务。"},{"label":"结束时间","type":"datetime","required":true,"hint":"实际宣布结束时间，精确到分钟。"},{"label":"记录人","type":"text","required":true,"hint":"填写本记录单的人员姓名与岗位。"},{"label":"结束条件核对","type":"multiselect","options":["业务恢复并验证","无二次加密/无残留威胁","外泄接口关闭","证据固定完成","对外双报闭环","报案/受理闭环","患者告知完成","舆情可控","网络出口/防火墙恢复","邮件系统恢复","办公终端恢复","医疗设备网络恢复"],"required":true,"hint":"按本场景节点说明逐项勾选已满足的条件；未满足项不得勾选，并在「残余风险与后续措施」写明责任人与补录时限。"}]'
 WHERE id = 'F18';
